//! Byte-for-byte checks of the decryptor against fixtures recorded from the reference
//! implementations. All credentials are synthetic.
//!
//! - `decrypt_binary*.json`: generated by fairplay-decrypt's `core.py`, which decrypts a
//!   fat binary in place; the port thins it, so the expected output is that slice.
//! - `binaries.json`, `ipas.json` and the `*.zip` inputs: generated by ipadecrypt's
//!   `internal/fairplay` at commit 7c82f86 with `go_fixtures/gen_test.go`.

use std::collections::BTreeMap;
use std::path::{Path, PathBuf};

use ipatool_appstore::IpaReader;
use ipatool_decrypt::{
    Credentials, Error, Options, arm_encryption_info, decrypt_binary, decrypt_ipa, derive_work16,
};
use sha2::{Digest, Sha256};

fn hex(s: &str) -> Vec<u8> {
    assert!(s.len().is_multiple_of(2), "hex string has even length");
    (0..s.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&s[i..i + 2], 16).expect("hex digit pair"))
        .collect()
}

fn field(value: &serde_json::Value, key: &str) -> Vec<u8> {
    hex(value[key].as_str().unwrap_or_default())
}

fn fixture(name: &str) -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("tests/fixtures")
        .join(name)
}

fn check_core_py(fixture: &str) {
    let value: serde_json::Value = serde_json::from_str(fixture).expect("fixture JSON");
    let credential = field(&value, "credential");
    let sinf = field(&value, "sinf");
    let supf = field(&value, "supf");
    let source = field(&value, "source");
    let expected = field(&value, "expected_output");
    let work = field(&value, "work16");
    let pages = usize::try_from(value["pages"].as_u64().expect("pages")).expect("page count");

    assert_eq!(
        derive_work16(&credential, &sinf).expect("work"),
        work.as_slice()
    );
    let info = arm_encryption_info(&source)
        .expect("Mach-O")
        .expect("encrypted");
    let (output, got_pages) = decrypt_binary(&source, &sinf, &supf, &credential)
        .expect("decrypt")
        .expect("encrypted");
    assert_eq!(got_pages, pages);
    assert_eq!(
        output,
        expected[info.base..info.base + info.size],
        "decrypted bytes differ from the Python oracle"
    );
}

#[test]
fn core_py_thin_arm64_two_pages_448_priv() {
    check_core_py(include_str!("fixtures/decrypt_binary.json"));
}

#[test]
fn core_py_fat32_arm64_one_page_440_priv() {
    check_core_py(include_str!("fixtures/decrypt_binary_fat440.json"));
}

#[test]
fn ipadecrypt_binaries() {
    let value: serde_json::Value =
        serde_json::from_str(include_str!("fixtures/binaries.json")).expect("fixture JSON");
    let cases = value["cases"].as_array().expect("cases");
    assert!(cases.len() >= 19);
    for case in cases {
        let name = case["name"].as_str().expect("name");
        let credential = field(case, "credential");
        let sinf = field(case, "sinf");
        if let Some(work) = case["work16"].as_str() {
            assert_eq!(
                derive_work16(&credential, &sinf).expect(name),
                hex(work).as_slice(),
                "{name}"
            );
        }
        let result = decrypt_binary(
            &field(case, "source"),
            &sinf,
            &field(case, "key_file"),
            &credential,
        );
        if let Some(error) = case["error"].as_str() {
            assert_eq!(result.expect_err(name).to_string(), error, "{name}");
            continue;
        }
        let result = result.expect(name);
        if !case["encrypted"].as_bool().expect("encrypted") {
            assert!(result.is_none(), "{name}");
            continue;
        }
        let (output, pages) = result.expect(name);
        assert_eq!(
            pages,
            usize::try_from(case["pages"].as_u64().expect("pages")).expect("page count"),
            "{name}"
        );
        assert!(
            output == field(case, "output"),
            "{name}: decrypted bytes differ from ipadecrypt"
        );
    }
}

fn sha256_hex(data: &[u8]) -> String {
    use std::fmt::Write as _;
    Sha256::digest(data)
        .iter()
        .fold(String::new(), |mut out, byte| {
            write!(out, "{byte:02x}").expect("writing to a String");
            out
        })
}

#[test]
fn ipadecrypt_ipas() {
    let value: serde_json::Value =
        serde_json::from_str(include_str!("fixtures/ipas.json")).expect("fixture JSON");
    let standard = field(&value, "credential");
    let arcade = field(&value, "arcade_credential");
    let dir = tempfile::tempdir().expect("temp dir");
    for run in value["runs"].as_array().expect("runs") {
        let name = run["name"].as_str().expect("name");
        let credentials = Credentials {
            standard: standard.clone(),
            arcade: run["arcade"]
                .as_bool()
                .expect("arcade")
                .then(|| arcade.clone()),
        };
        let options = Options {
            skip_appex: run["skip_appex"].as_bool().expect("skip_appex"),
            keep_watch: run["keep_watch"].as_bool().expect("keep_watch"),
        };
        let output = dir.path().join(format!("{name}.ipa"));
        let result = decrypt_ipa(
            &fixture(run["input"].as_str().expect("input")),
            &output,
            &credentials,
            options,
        );
        if let Some(error) = run["error"].as_str() {
            assert_eq!(result.expect_err(name).to_string(), error, "{name}");
            assert!(!output.exists(), "{name}");
            continue;
        }
        let still: Vec<String> = run["still_encrypted"]
            .as_array()
            .map_or_else(Vec::new, |names| {
                names
                    .iter()
                    .map(|name| name.as_str().expect("name").to_owned())
                    .collect()
            });
        if !still.is_empty() {
            // ipadecrypt writes this IPA, then its verification pass rejects and deletes it.
            let Err(Error::Verify(verification)) = result else {
                panic!("{name}: expected a verification failure, got {result:?}");
            };
            assert_eq!(verification.still_encrypted, still, "{name}");
            assert!(!output.exists(), "{name}");
            continue;
        }
        let summary = result.expect(name);
        let count = |key: &str| usize::try_from(run[key].as_u64().expect(key)).expect(key);
        assert_eq!(summary.binaries, count("binaries"), "{name}");
        assert_eq!(summary.pages, count("pages"), "{name}");
        assert_eq!(summary.verified, count("scanned"), "{name}");

        let reader = IpaReader::open(&output).expect("output IPA");
        let got: BTreeMap<String, String> = reader
            .members()
            .map(|(member, data)| (member.to_owned(), sha256_hex(&data.expect("member"))))
            .collect();
        let want: BTreeMap<String, String> = run["members"]
            .as_object()
            .expect("members")
            .iter()
            .map(|(member, sum)| (member.clone(), sum.as_str().expect("sum").to_owned()))
            .collect();
        assert_eq!(got, want, "{name}");
    }
}
